import{_ as a,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据搬出","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/reg_data_store"},{"text":"unalign_store","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/unalign_store"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/unalign_store.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/unalign_store.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793173587000}'),l={name:"api/SIMD-API/tensor_api/reg_vector_compute/reg_data_store/unalign_store.md"};function e(t,s,o,d,r,i){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>unalign_store</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/reg_data_store.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p><code>unalign_store</code>用于将<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>中的数据连续搬出到非32字节对齐的Unified Buffer（UB）地址。对象内部维护一个非对齐搬出寄存器，提供以下两个操作：</p><ul><li><code>store</code>：将源寄存器前<code>count</code>个元素连续搬出。已形成的32字节对齐主块写入UB，非对齐尾块暂存到对象内部的非对齐寄存器中，供下一次连续搬出拼接。</li><li><code>flush</code>：将非对齐寄存器中暂存的尾块写入UB。一次连续搬出序列结束后必须调用该接口完成收尾。</li></ul><p><code>store</code>使用<code>src.reg</code>，忽略<code>src.mask</code>。有效搬出元素数由<code>count</code>指定，不能使用mask替代<code>count</code>。本接口不会自动推进目的Tensor或坐标，调用者须根据累计搬出元素数指定下一次连续写入地址。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">unalign_store</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="nf">unalign_store</span><span class="p">()</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">default</span><span class="p">;</span>

<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">RegDataType</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">store</span><span class="p">(</span>
<span class="w">        </span><span class="n">Tensor</span><span class="w"> </span><span class="n">dst_tile</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>

<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">RegDataType</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">store</span><span class="p">(</span>
<span class="w">        </span><span class="n">Tensor</span><span class="w"> </span><span class="n">dst_tile</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span>
<span class="w">        </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">RegDataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>

<span class="w">    </span><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="o">&gt;</span>
<span class="w">    </span><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">flush</span><span class="p">(</span><span class="n">Tensor</span><span class="w"> </span><span class="n">dst_base</span><span class="p">,</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>
<span class="p">};</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>Tensor</td><td>目的Tensor类型，由函数实参自动推导，必须位于UB。</td></tr><tr><td>Coord</td><td><code>store</code>的目的Tensor坐标类型，由函数实参自动推导。</td></tr><tr><td>RegDataType</td><td>源寄存器元素类型，由函数实参自动推导。除<code>int4b_t</code>映射为<code>int4x2_t</code>外，必须与目的Tensor元素类型一致。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst_tile</td><td>输出</td><td>本次搬出的目的Tensor。不传入坐标时，写入地址为<code>dst_tile.engine().begin().get()</code>。Tensor视图按值传入，不会修改调用者的视图，但会写入其指向的UB。</td></tr><tr><td>coord（store）</td><td>输入</td><td>本次搬出起始元素在<code>dst_tile</code>逻辑布局中的坐标，实际写入地址为<code>(dst_tile.data() + dst_tile.layout()(coord)).get()</code>。</td></tr><tr><td>src</td><td>输入</td><td>源<code>reg_tensor</code>，<code>reg</code>必须初始化，<code>mask</code>不参与搬出。</td></tr><tr><td>count</td><td>输入</td><td>本次搬出的元素个数，类型为<code>uint32_t</code>，不超过单个矢量寄存器可容纳的元素个数。</td></tr><tr><td>dst_base</td><td>输出</td><td>收尾使用的目的Tensor，其起始地址为本次连续搬出序列第一次<code>store</code>的实际写入地址。</td></tr><tr><td>coord（flush）</td><td>输入</td><td>类型为<code>int32_t</code>，传给底层收尾接口的元素偏移量，应为本次连续搬出序列各次<code>count</code>之和。它不是<code>make_coord</code>生成的逻辑坐标，也不是字节偏移。</td></tr></tbody></table><p><code>flush</code>使用的收尾地址由<code>dst_base.engine().begin().get()</code>和元素偏移<code>coord</code>确定。若第一次<code>store</code>指定了非零坐标，应将该坐标对应的Tensor视图作为<code>dst_base</code>，不能直接用未偏移的原Tensor配合本序列元素总数进行收尾。</p><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><table><thead><tr><th>目的Tensor元素类型</th><th>源寄存器类型</th></tr></thead><tbody><tr><td><code>int4b_t</code></td><td><code>reg_tensor&lt;int4x2_t&gt;</code>。</td></tr><tr><td><code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int8_t</code>、<code>uint8_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int32_t</code>、<code>uint32_t</code>、<code>float</code></td><td>对应元素类型的<code>reg_tensor</code>。</td></tr><tr><td><code>int64_t</code></td><td><code>reg_tensor&lt;int64_t&gt;</code>。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><code>store</code>和<code>flush</code>均无返回值。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>目的地址无需32字节对齐，但必须满足元素类型的对齐要求，实际写入范围不能超出有效UB空间。</li><li>同一连续搬出序列必须复用同一个<code>unalign_store</code>对象，所有目的Tensor的元素类型必须一致。</li><li>相邻两次<code>store</code>的实际写入地址必须连续，即下一次起始地址为上一次起始地址加已搬出数据长度。地址不连续时，应先对当前序列调用<code>flush</code>，再开始新的搬出序列。</li><li>每个序列的全部<code>store</code>完成后，使用首次写入地址对应的<code>dst_base</code>以及累计搬出元素数调用一次<code>flush</code>。不能遗漏收尾，也不能在尚未进行<code>store</code>时调用<code>flush</code>。</li><li><code>count</code>不得超过一个寄存器容量；例如<code>uint8_t</code>为<code>VL / sizeof(uint8_t)</code>个元素，<code>float</code>为<code>VL / sizeof(float)</code>个元素。</li><li><code>store</code>的坐标维数必须与Tensor布局匹配，坐标不能越界；<code>flush</code>的元素偏移及最终地址必须在合法范围内。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例连续复制<code>uint8_t</code>数据，最后一段通过<code>count</code>控制有效搬出数量。源、目的Tensor均为一维UB Tensor，起始地址可非32字节对齐；<code>total_elements</code>大于0且不超过<code>int32_t</code>上限。源UB空间必须为最后一次完整VL读取及前置缓存预留合法空间，目的UB空间必须覆盖全部写入数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/experimental/vector_ops.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyUnaligned</span><span class="p">(</span>
<span class="w">    </span><span class="n">SrcTensor</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">DstTensor</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">total_elements</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">elements_per_register</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">get_vf_len</span><span class="p">()</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">uint8_t</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">unalign_load</span><span class="w"> </span><span class="n">loader</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">unalign_store</span><span class="w"> </span><span class="n">storer</span><span class="p">;</span>
<span class="w">    </span><span class="n">loader</span><span class="p">.</span><span class="n">prepare</span><span class="p">(</span><span class="n">src</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">total_elements</span><span class="p">;</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">elements_per_register</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">remaining</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">total_elements</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">offset</span><span class="p">;</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">remaining</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">elements_per_register</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">remaining</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">elements_per_register</span><span class="p">;</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">coord</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="n">offset</span><span class="p">);</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">loader</span><span class="p">.</span><span class="n">load</span><span class="p">(</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>
<span class="w">        </span><span class="n">storer</span><span class="p">.</span><span class="n">store</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">storer</span><span class="p">.</span><span class="n">flush</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">total_elements</span><span class="p">));</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const h=a(l,[["render",e]]);export{w as __pageData,h as default};
